:root {
  --bg:#0b0e14; --bg-2:#111621; --card:#141a26; --card-2:#1a2130;
  --line:#232c3d; --line-2:#2f3a4f;
  --fg:#e6edf7; --fg-2:#a9b6cc; --fg-3:#7c8aa3;
  --acc:#5eead4; --acc-2:#0f766e;
  --ok:#4ade80; --warn:#fbbf24; --bad:#f87171; --info:#7dd3fc;
  --focus:#fbbf24;
  --radius:12px; --radius-s:8px;
  --shadow:0 8px 30px rgba(0,0,0,.45);
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
[data-theme="light"] {
  --bg:#f6f8fc; --bg-2:#eef2f9; --card:#ffffff; --card-2:#f2f5fa;
  --line:#dde4ef; --line-2:#c6d0e0;
  --fg:#101725; --fg-2:#41506b; --fg-3:#67748d;
  --acc:#0d9488; --acc-2:#0f766e;
  --ok:#15803d; --warn:#b45309; --bad:#b91c1c; --info:#0369a1;
  --focus:#b45309;
  --shadow:0 8px 30px rgba(16,24,40,.12);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;background:var(--bg);color:var(--fg);
  font:16px/1.55 var(--sans);
  -webkit-font-smoothing:antialiased;
}
h1,h2,h3{margin:0;line-height:1.25;font-weight:650;letter-spacing:-.01em}
code,pre,.mono{font-family:var(--mono)}
a{color:var(--acc)}
.wrap{width:min(1180px,100% - 2rem);margin-inline:auto}
.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
kbd{
  font:600 11px/1 var(--mono);border:1px solid var(--line-2);
  border-bottom-width:2px;border-radius:4px;padding:2px 4px;background:var(--card-2);color:var(--fg-2)
}
:focus-visible{outline:3px solid var(--focus);outline-offset:2px;border-radius:6px}
.skip{
  position:absolute;left:.5rem;top:-3rem;z-index:100;background:var(--acc);color:#04211d;
  padding:.6rem .9rem;border-radius:0 0 var(--radius-s) var(--radius-s);font-weight:650;transition:top .15s
}
.skip:focus{top:0}
.top{position:sticky;top:0;z-index:30;background:color-mix(in srgb,var(--bg) 88%,transparent);
  backdrop-filter:saturate(140%) blur(8px);border-bottom:1px solid var(--line)}
.top-in{display:flex;align-items:center;gap:.75rem;padding:.7rem 0;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:.6rem;margin-right:auto;min-width:0}
.logo{width:26px;height:26px;border-radius:7px;flex:0 0 auto;
  background:conic-gradient(from 210deg,var(--acc),#818cf8,var(--acc));box-shadow:0 0 0 1px var(--line-2)}
.brand h1{font-size:1.05rem}
.sub{margin:0;font-size:.74rem;color:var(--fg-3);font-family:var(--mono);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:52vw;
  height:1.15em}
.views{display:flex;gap:.25rem;background:var(--card);border:1px solid var(--line);border-radius:999px;padding:.2rem}
.tab{
  font:600 .82rem/1 var(--sans);color:var(--fg-2);background:none;border:0;cursor:pointer;
  padding:.45rem .8rem;border-radius:999px
}
.tab:hover{color:var(--fg)}
.tab.is-on{background:var(--acc);color:#04211d}
.icon-btn{
  width:34px;height:34px;display:grid;place-items:center;cursor:pointer;
  background:var(--card);color:var(--fg-2);border:1px solid var(--line);border-radius:var(--radius-s);font-size:.95rem
}
.icon-btn:hover{color:var(--fg);border-color:var(--line-2)}
.controls{padding:1.1rem 0 .6rem}
.search-row{display:grid;gap:.35rem}
#q{
  width:100%;font:15px/1.4 var(--sans);color:var(--fg);background:var(--card);
  border:1px solid var(--line-2);border-radius:var(--radius);padding:.7rem .85rem
}
#q::placeholder{color:var(--fg-3)}
#q:focus{border-color:var(--acc)}
.hint{font-size:.72rem;color:var(--fg-3)}
.filter-grid{display:grid;gap:.7rem;margin-top:.9rem}
fieldset{border:0;margin:0;padding:0;min-width:0}
legend{font:600 .7rem/1 var(--sans);letter-spacing:.09em;text-transform:uppercase;color:var(--fg-3);padding:0 0 .35rem}
.chips{
  display:flex;flex-wrap:nowrap;overflow-x:auto;overflow-y:hidden;
  gap:.3rem;min-height:28px;padding-bottom:2px;scrollbar-width:thin;
  scrollbar-color:var(--line-2) transparent;
}
.chips::-webkit-scrollbar{height:4px}
.chips::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:4px}
.chip{
  font:500 .78rem/1 var(--sans);color:var(--fg-2);background:var(--card);
  border:1px solid var(--line);border-radius:999px;padding:.4rem .68rem;cursor:pointer;
  flex:0 0 auto;white-space:nowrap
}
.chip:hover{color:var(--fg);border-color:var(--line-2)}
.chip[aria-pressed="true"]{background:var(--acc);border-color:var(--acc);color:#04211d;font-weight:650}
.result-bar{display:flex;align-items:center;gap:.8rem;margin:.9rem 0 .2rem;flex-wrap:nowrap;min-height:22px}
#count{margin:0;font-size:.82rem;color:var(--fg-2);font-family:var(--mono);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1 1 auto;min-width:0}
.link-btn{background:none;border:0;color:var(--acc);cursor:pointer;font:600 .8rem var(--sans);padding:.2rem;text-decoration:underline;flex:0 0 auto}
.view{padding-bottom:3rem}
.view:focus{outline:none}
.tasks{list-style:none;margin:0;padding:0;display:grid;gap:.6rem;align-content:start;min-height:100vh}
.task{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
  padding:.85rem .95rem;position:relative
}
.task:hover{border-color:var(--line-2);background:var(--card-2)}
.task:focus-within{border-color:var(--acc-2)}
.t-btn{display:block;width:100%;text-align:left;background:none;border:0;padding:0;margin:0;cursor:pointer;color:inherit;font:inherit}
.t-btn:focus-visible{outline:3px solid var(--focus);outline-offset:3px;border-radius:6px}
.task::before{
  content:"";position:absolute;left:0;top:12px;bottom:12px;width:3px;border-radius:0 3px 3px 0;background:var(--fg-3)
}
.task[data-s="open"]::before{background:var(--info)}
.task[data-s="claimed"]::before{background:var(--warn)}
.task[data-s="submitted"]::before{background:var(--acc)}
.task[data-s="verified"]::before{background:var(--ok)}
.task[data-s="closed"]::before{background:var(--fg-3)}
.t-top{display:flex;gap:.6rem;align-items:flex-start;justify-content:space-between}
.t-title{font-size:.98rem;font-weight:600;margin:0;overflow-wrap:anywhere}
.t-sum{
  margin:.35rem 0 0;color:var(--fg-2);font-size:.83rem;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere
}
.t-meta{display:flex;flex-wrap:wrap;gap:.35rem;margin-top:.55rem;align-items:center}
.pill{
  font:600 .68rem/1 var(--mono);letter-spacing:.03em;padding:.32rem .5rem;border-radius:6px;
  background:var(--card-2);color:var(--fg-2);border:1px solid var(--line);white-space:nowrap
}
.pill.bounty{background:color-mix(in srgb,var(--ok) 16%,transparent);color:var(--ok);border-color:color-mix(in srgb,var(--ok) 34%,transparent)}
.pill.free{color:var(--fg-3)}
.pill.s-open{color:var(--info)} .pill.s-claimed{color:var(--warn)}
.pill.s-submitted{color:var(--acc)} .pill.s-verified{color:var(--ok)} .pill.s-closed{color:var(--fg-3)}
.pill.settled{background:color-mix(in srgb,var(--ok) 20%,transparent);color:var(--ok);border-color:color-mix(in srgb,var(--ok) 40%,transparent)}
.age{margin-left:auto;font:500 .7rem var(--mono);color:var(--fg-3)}
.empty{padding:2.5rem 1rem;text-align:center;color:var(--fg-2)}
.panel{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:1rem;margin-top:.5rem}
.panel h2{font-size:1.05rem}
.panel-sub{margin:.25rem 0 .9rem;font-size:.8rem;color:var(--fg-3);font-family:var(--mono)}
.table-scroll{overflow-x:auto}
.tbl{width:100%;border-collapse:collapse;font-size:.82rem;min-width:560px}
.tbl th,.tbl td{text-align:left;padding:.55rem .5rem;border-bottom:1px solid var(--line);vertical-align:top}
.tbl th{font:600 .68rem/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--fg-3)}
.tbl td.mono{font-family:var(--mono);font-size:.74rem;color:var(--fg-2);overflow-wrap:anywhere}
.tbl tr:hover td{background:var(--card-2)}
.agents{list-style:none;margin:0;padding:0;display:grid;gap:.55rem}
.agent{background:var(--card-2);border:1px solid var(--line);border-radius:var(--radius-s);padding:.7rem .8rem}
.agent h3{font-size:.9rem;overflow-wrap:anywhere}
.agent .aid{font:500 .7rem var(--mono);color:var(--fg-3);overflow-wrap:anywhere}
.agent p{margin:.35rem 0 0;font-size:.82rem;color:var(--fg-2)}
.scrim{position:fixed;inset:0;background:rgba(2,6,14,.62);z-index:40}
.drawer{
  position:fixed;inset-block:0;right:0;width:min(680px,100%);z-index:50;
  background:var(--bg-2);border-left:1px solid var(--line);box-shadow:var(--shadow);
  overflow-y:auto;overscroll-behavior:contain
}
.drawer-in{padding:1rem 1.1rem 3rem}
.drawer-top{display:flex;align-items:center;gap:.6rem;justify-content:space-between;margin-bottom:.5rem}
.crumbs{margin:0;font:500 .72rem var(--mono);color:var(--fg-3);overflow-wrap:anywhere}
#d-title{font-size:1.15rem;overflow-wrap:anywhere}
.badges{display:flex;flex-wrap:wrap;gap:.35rem;margin:.6rem 0}
.meta{display:grid;grid-template-columns:auto 1fr;gap:.3rem .8rem;margin:.8rem 0 0;font-size:.8rem}
.meta dt{color:var(--fg-3);font-family:var(--mono);font-size:.74rem}
.meta dd{margin:0;overflow-wrap:anywhere}
.sec{font-size:.74rem;letter-spacing:.09em;text-transform:uppercase;color:var(--fg-3);margin:1.3rem 0 .5rem}
.prose{font-size:.88rem;color:var(--fg-2);white-space:pre-wrap;overflow-wrap:anywhere}
.prose a{overflow-wrap:anywhere}
.pre{
  background:var(--card);border:1px solid var(--line);border-radius:var(--radius-s);
  padding:.7rem;font-size:.75rem;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--fg-2);margin:0
}
.foot{border-top:1px solid var(--line);padding:1.1rem 0 2rem;margin-top:1rem}
.foot p{margin:0;font-size:.76rem;color:var(--fg-3);max-width:70ch}
.foot code{font-size:.72rem;color:var(--fg-2)}
@media (min-width:640px){
  .filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sub{max-width:40vw}
}
@media (min-width:900px){
  .filter-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
  .drawer{width:min(720px,92%)}
  .agents{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (prefers-reduced-motion:reduce){
  *{animation:none!important;transition:none!important;scroll-behavior:auto!important}
}

